{
  "plans": [
    {
      "name": "tfidf_logistic_baseline",
      "steps": [
        {
          "kind": "vectorizer",
          "action": "reuse",
          "operator_ref": "TfidfTextVectorizer@1",
          "params": {
            "column": "text",
            "analyzer": "char_wb",
            "ngram_range": [
              1,
              2
            ]
          },
          "rationale": "针对中文短文本，采用字符级 1-2 gram TF-IDF 向量化处理，符合最佳实践。",
          "evidence_ids": [
            "Operator:TfidfTextVectorizer@1",
            "Lesson:631c1a72"
          ]
        },
        {
          "kind": "model",
          "action": "reuse",
          "operator_ref": "LogisticRegressionModel@1",
          "params": {
            "class_weight": "balanced",
            "C": 1.0,
            "max_iter": 1000
          },
          "rationale": "针对样本不平衡问题，设置 class_weight='balanced' 以提升宏平均 F1 分数。",
          "evidence_ids": [
            "Operator:LogisticRegressionModel@1",
            "Lesson:9e9e77d6"
          ]
        }
      ],
      "rationale": "使用高效的文本向量化方案配合平衡权重逻辑回归，是处理中文短文本分类的经典基线方案。"
    },
    {
      "name": "tfidf_balanced_linear_model",
      "steps": [
        {
          "kind": "synthesize",
          "action": "synthesize",
          "synth_spec": {
            "name": "IdColumnDropper",
            "kind": "feature",
            "purpose": "删除数据中的 ID 类列，防止过拟合",
            "inputs": "含 ticket_id 的数据集",
            "outputs": "排除标识列后的数据集"
          },
          "rationale": "在建模前移除与任务无关的标识符列，防止模型过拟合。",
          "evidence_ids": []
        },
        {
          "kind": "vectorizer",
          "action": "reuse",
          "operator_ref": "TfidfTextVectorizer@1",
          "params": {
            "column": "text",
            "analyzer": "char_wb",
            "ngram_range": [
              1,
              2
            ],
            "max_features": 30000
          },
          "rationale": "通过增加最大特征数，捕获更多词汇信息，进一步提升文本表达能力。",
          "evidence_ids": [
            "Operator:TfidfTextVectorizer@1"
          ]
        },
        {
          "kind": "model",
          "action": "reuse",
          "operator_ref": "LogisticRegressionModel@1",
          "params": {
            "class_weight": "balanced",
            "C": 0.5,
            "max_iter": 1000
          },
          "rationale": "通过调整正则化系数 C，降低过拟合风险，并继续使用平衡权重解决类别不平衡。",
          "evidence_ids": [
            "Operator:LogisticRegressionModel@1",
            "Lesson:9e9e77d6"
          ]
        }
      ],
      "rationale": "在基线基础上引入标识列剔除算子并微调正则化参数，旨在提高模型泛化能力以满足 F1 指标需求。"
    }
  ]
}

